    season_sig = _rivalry_cache_signature(conn, season_key)
    feud_event_row = conn.execute("SELECT COALESCE(MAX(id), 0) AS n FROM feud_events").fetchone()
    latest_feud_event_id = int(feud_event_row["n"] or 0)
