@app.route("/api/hunter-badge-feed/<username>")
def hunter_badge_feed_api(username):
    data = _hunter_badges_snapshot(username)
    if not data.get("success"):
        return jsonify(data), 404
    by_key = {b["key"]: b for b in data.get("badges", [])}
    conn = db()
    rows = conn.execute(
        "SELECT badge_key, unlocked_at FROM hunter_badge_unlocks WHERE username = ? ORDER BY unlocked_at DESC, id DESC LIMIT 24",
        (username,)
    ).fetchall()
    conn.close()
    items = []
    for row in rows:
        badge = by_key.get(row["badge_key"])
        if not badge or not badge.get("unlocked"):
            continue
        items.append({
            "key": badge["key"], "icon": badge["icon"], "title": badge["title"], "detail": badge["detail"],
            "unlocked_at": row["unlocked_at"],
            "share_url": f"/badge/{urllib.parse.quote(username)}/{urllib.parse.quote(badge['key'])}"
        })
    return jsonify({
        "success": True, "username": username, "count": len(items), "items": items,
        "policy": "The feed records first-seen BL3 achievement unlocks only; badges are not tokens or financial assets."
    })


