# ===== V18.3 HUNTER LOADOUT + PROFILE AURAS =====
def _hunter_loadout_snapshot(username):
    username = str(username or "").strip()
    badges = _hunter_badges_snapshot(username)
    if not badges.get("success"):
        return {"success": False, "message": "Hunter not found"}
    unlocked = {b["key"]: b for b in badges.get("badges", []) if b.get("unlocked")}
    streak = _hunter_streak_snapshot(username)
    streak_days = int(streak.get("streak") or 0) if streak.get("success") else 0
    public = _hunter_public_data(username) or {}
    aura_catalog = [
        {"key":"signal","icon":"📡","label":"SIGNAL","detail":"Default BL3 signal aura.","unlocked":True},
        {"key":"violet","icon":"🟣","label":"VIOLET","detail":"Unlock with 500 XP or SIGNAL 500.","unlocked":int(public.get("xp") or 0) >= 500 or "signal_500" in unlocked},
        {"key":"ember","icon":"🔥","label":"EMBER","detail":"Unlock with a 7-day streak.","unlocked":streak_days >= 7 or "on_fire" in unlocked},
        {"key":"crown","icon":"👑","label":"CROWN","detail":"Unlock while holding the seasonal Crown or LEGEND LOOP.","unlocked":bool((public.get("season") or {}).get("is_crown")) or "legend_loop" in unlocked},
    ]
    aura_by_key = {a["key"]: a for a in aura_catalog}
    conn = db()
    row = conn.execute("SELECT aura_key, badge_keys_json, updated_at FROM hunter_profile_loadouts WHERE username = ?", (username,)).fetchone()
    conn.close()
    aura_key = "signal"
    badge_keys = []
    updated_at = None
    if row is not None:
        aura_key = str(row["aura_key"] or "signal")
        updated_at = row["updated_at"]
        try:
            badge_keys = [str(x) for x in json.loads(row["badge_keys_json"] or "[]") if str(x) in unlocked][:3]
        except Exception:
            badge_keys = []
    if aura_key not in aura_by_key or not aura_by_key[aura_key]["unlocked"]:
        aura_key = "signal"
    if not badge_keys:
        featured = badges.get("featured_badge")
        if featured and featured.get("key") in unlocked:
            badge_keys = [featured["key"]]
        else:
            badge_keys = list(unlocked.keys())[:3]
    selected = [unlocked[k] for k in badge_keys if k in unlocked][:3]
    return {
        "success": True, "username": username, "aura_key": aura_key, "aura": aura_by_key[aura_key],
        "auras": aura_catalog, "badge_keys": [b["key"] for b in selected], "showcase_badges": selected,
        "badges": badges.get("badges", []), "updated_at": updated_at,
        "policy": "Profile auras and showcase slots are cosmetic BL3 identity settings only; they do not represent tokens, custody, or payout rights."
    }


@app.route("/api/hunter-loadout/<username>", methods=["GET", "POST"])
def hunter_profile_loadout_api(username):
    data = _hunter_loadout_snapshot(username)
    if not data.get("success"):
        return jsonify(data), 404
    if request.method == "GET":
        return jsonify(data)
    if session.get("authenticated_username") != username:
        return jsonify({"success": False, "message": "Sign in with this Hunter ID to edit the public loadout."}), 401
    payload = request.get_json(silent=True) or {}
    requested_aura = str(payload.get("aura_key") or "signal").strip()
    allowed_auras = {a["key"] for a in data.get("auras", []) if a.get("unlocked")}
    if requested_aura not in allowed_auras:
        return jsonify({"success": False, "message": "That aura is not unlocked."}), 400
    unlocked = {b["key"] for b in data.get("badges", []) if b.get("unlocked")}
    requested_badges = payload.get("badge_keys") or []
    if not isinstance(requested_badges, list):
        return jsonify({"success": False, "message": "badge_keys must be a list."}), 400
    clean = []
    for key in requested_badges:
        key = str(key or "").strip()
        if key in unlocked and key not in clean:
            clean.append(key)
        if len(clean) >= 3:
            break
    now_iso = datetime.utcnow().isoformat() + "Z"
    conn = db()
    conn.execute(
        """INSERT INTO hunter_profile_loadouts(username, aura_key, badge_keys_json, updated_at)
           VALUES (?, ?, ?, ?)
           ON CONFLICT(username) DO UPDATE SET aura_key = excluded.aura_key, badge_keys_json = excluded.badge_keys_json, updated_at = excluded.updated_at""",
        (username, requested_aura, json.dumps(clean, separators=(",", ":")), now_iso)
    )
    conn.commit()
    conn.close()
    fresh = _hunter_loadout_snapshot(username)
    return jsonify({"success": True, "message": "🧬 Hunter Loadout saved", **fresh})


# ===== V18.3 HUNTER PASSPORT + REPUTATION SNAPSHOT =====
def _hunter_passport_snapshot(username):
    public = _hunter_public_data(username)
    if public is None:
        return None
    badges = _hunter_badges_snapshot(username) or {"badges": [], "featured_badge": None, "unlocked_count": 0}
    loadout = _hunter_loadout_snapshot(username) or {}
    streak = _hunter_streak_snapshot(username) or {}
    trophies = _hunter_trophies(username) or {"count": 0}
    title = _hunter_title(username) or {"title": "HUNTER", "icon": "👾", "tier": "UNRANKED"}
    aura = loadout.get("aura") or {"label": "SIGNAL", "icon": "📡"}
    verified = bool(public.get("wallet_verified"))
    proof_count = int(verified) + int((badges.get("unlocked_count") or 0) > 0) + int((trophies.get("count") or 0) > 0) + int((public.get("wins") or 0) > 0)
    identity_state = "PROVEN" if proof_count >= 3 else ("BUILDING" if proof_count >= 1 else "NEW")
    root = request.url_root.rstrip("/")
    return {"success": True, "username": username, "identity_state": identity_state, "title": title.get("title") or "HUNTER", "title_icon": title.get("icon") or "👾", "title_tier": title.get("tier") or "UNRANKED", "aura": aura.get("label") or "SIGNAL", "aura_icon": aura.get("icon") or "📡", "reputation": int(public.get("reputation") or 0), "xp": int(public.get("xp") or 0), "wins": int(public.get("wins") or 0), "network": int(public.get("network") or 0), "wallet_verified": verified, "badges_unlocked": int(badges.get("unlocked_count") or 0), "featured_badge": badges.get("featured_badge"), "trophies": int(trophies.get("count") or 0), "streak": int(streak.get("streak") or 0), "momentum": streak.get("momentum") or "DORMANT", "passport_url": f"{root}/passport/{urllib.parse.quote(username)}", "profile_url": f"{root}/hunter/{urllib.parse.quote(username)}", "snapshot_utc": datetime.utcnow().isoformat() + "Z", "principle": "Public reputation snapshot derived from current BL3 activity. Not a financial credential, identity document, token, or guarantee."}

@app.route("/api/hunter-passport/<username>")
def hunter_passport_api(username):
    snap = _hunter_passport_snapshot(username)
    if snap is None:
        return jsonify({"success": False, "message": "Hunter not found"}), 404
    return jsonify(snap)

@app.route("/passport/<username>")
def hunter_passport_page(username):
    d = _hunter_passport_snapshot(username)
    if d is None:
        return "Hunter not found", 404
    esc = lambda v: html.escape(str(v or ""))
    fb = d.get("featured_badge") or {}
    featured = f"{esc(fb.get('icon') or '🏅')} {esc(fb.get('title') or 'No featured badge yet')}"
