# ===== V18.3 HUNTER PROOF LEDGER + REPUTATION TIMELINE =====
def _hunter_proof_ledger_snapshot(username, limit=40):
    public = _hunter_public_data(username)
    if public is None:
        return None
    try:
        limit = max(1, min(100, int(limit or 40)))
    except Exception:
        limit = 40
    conn = db()
    events = []
    def add(source, row_id, at, icon, title, detail, weight=1):
        raw = f"{username}|{source}|{row_id}"
        proof_id = hashlib.sha256(raw.encode("utf-8")).hexdigest()[:20]
        events.append({"proof_id": proof_id, "source": source, "at": str(at or ""), "icon": icon, "title": title, "detail": detail, "weight": int(weight or 0)})

    for r in conn.execute("SELECT id, points, reason, created_at FROM reputation_events WHERE username = ? ORDER BY id DESC LIMIT 120", (username,)).fetchall():
        pts = int(r["points"] or 0)
        add("reputation", r["id"], r["created_at"], "📡", "Reputation signal", f"{pts:+d} REP · {r['reason'] or 'activity'}", max(1, abs(pts)))
    for r in conn.execute("SELECT id, quest, date FROM quests WHERE username = ? ORDER BY id DESC LIMIT 120", (username,)).fetchall():
        add("quest", r["id"], r["date"], "⚡", "Quest completed", str(r["quest"] or "quest"), 1)
    for r in conn.execute("SELECT id, cast_url, date FROM share_claims WHERE username = ? ORDER BY id DESC LIMIT 80", (username,)).fetchall():
        add("cast", r["id"], r["date"], "📢", "Cast verified", "Verified BL3 cast proof", 2)
    for r in conn.execute("SELECT s.id, s.arena_id, s.status, s.created_at, COALESCE(a.title,'Arena') AS arena_title FROM arena_submissions s LEFT JOIN arenas a ON a.id=s.arena_id WHERE s.username = ? ORDER BY s.id DESC LIMIT 100", (username,)).fetchall():
        add("arena", r["id"], r["created_at"], "🎯", "Arena proof submitted", f"{r['arena_title']} · {r['status'] or 'submitted'}", 3)
    for r in conn.execute("SELECT id, challenger, opponent, winner, created_at FROM creature_battles WHERE challenger = ? OR opponent = ? ORDER BY id DESC LIMIT 120", (username, username)).fetchall():
        won = str(r["winner"] or "") == username
        other = r["opponent"] if r["challenger"] == username else r["challenger"]
        add("clash", r["id"], r["created_at"], "⚔️", "Alpha Clash " + ("won" if won else "completed"), f"vs {other or 'Hunter'}", 4 if won else 2)
    badge_snapshot = _hunter_badges_snapshot(username) or {}
    badge_map = {b.get("key"): b for b in badge_snapshot.get("badges", [])}
    for r in conn.execute("SELECT id, badge_key, unlocked_at FROM hunter_badge_unlocks WHERE username = ? ORDER BY id DESC LIMIT 80", (username,)).fetchall():
        badge = badge_map.get(r["badge_key"]) or {}
        add("badge", r["id"], r["unlocked_at"], badge.get("icon") or "🏅", "Achievement unlocked", badge.get("title") or str(r["badge_key"] or "Badge"), 5)
    conn.close()
    events.sort(key=lambda x: (x.get("at") or "", x.get("proof_id") or ""), reverse=True)
    full_count = len(events)
    score = sum(int(e.get("weight") or 0) for e in events)
    canonical = {
        "username": username,
        "reputation": int(public.get("reputation") or 0),
        "xp": int(public.get("xp") or 0),
        "wins": int(public.get("wins") or 0),
        "events": [{k: e[k] for k in ("proof_id", "source", "at", "title", "detail", "weight")} for e in events]
    }
    digest = hashlib.sha256(json.dumps(canonical, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).hexdigest()
    proof_count = int(bool(public.get("wallet_verified"))) + int(full_count >= 1) + int((public.get("wins") or 0) > 0)
    identity_state = "PROVEN" if proof_count >= 3 else ("BUILDING" if proof_count >= 1 else "NEW")
    return {
        "success": True,
        "username": username,
        "identity_state": identity_state,
        "reputation": int(public.get("reputation") or 0),
        "xp": int(public.get("xp") or 0),
        "wins": int(public.get("wins") or 0),
        "event_count": full_count,
        "proof_score": score,
        "digest": digest,
        "events": events[:limit],
        "principle": "Derived from BL3 application records. Digest fingerprints this ledger content; it is not an onchain attestation or external identity verification."
    }


