# ===== V18.3 PROOF VAULT + BUNDLE HISTORY =====
def _proof_vault_entry(row):
    data = _proof_bundle_row_to_public(row, include_payload=True)
    payload = data.pop("payload", None) or {}
    passport = payload.get("passport") or {}
    ledger = payload.get("ledger") or {}
    integrity = _verify_proof_bundle_row(row)
    return {
        **data,
        "integrity": "VALID" if integrity.get("valid") else "INVALID",
        "identity_state": passport.get("identity_state") or "NEW",
        "reputation": int(passport.get("reputation") or 0),
        "xp": int(passport.get("xp") or 0),
        "wins": int(passport.get("wins") or 0),
        "proof_events": int(ledger.get("event_count") or 0),
        "proof_score": int(ledger.get("proof_score") or 0),
    }


def _proof_vault_snapshot(username, limit=30):
    try:
        limit = max(1, min(int(limit or 30), 100))
    except Exception:
        limit = 30
    public = _hunter_public_snapshot(username)
    if not public:
        return None
    conn = db()
    rows = conn.execute("SELECT * FROM hunter_proof_bundles WHERE username = ? ORDER BY id DESC LIMIT ?", (username, limit)).fetchall()
    conn.close()
    entries = [_proof_vault_entry(r) for r in rows]
    latest = entries[0] if entries else None
    previous = entries[1] if len(entries) > 1 else None
    delta = None
    if latest and previous:
        delta = {
            "reputation": latest["reputation"] - previous["reputation"],
            "xp": latest["xp"] - previous["xp"],
            "wins": latest["wins"] - previous["wins"],
            "proof_events": latest["proof_events"] - previous["proof_events"],
            "proof_score": latest["proof_score"] - previous["proof_score"],
        }
    valid_count = sum(1 for x in entries if x["integrity"] == "VALID")
    return {
        "success": True,
        "username": username,
        "bundle_count": len(entries),
        "valid_count": valid_count,
        "latest": latest,
        "previous": previous,
        "latest_delta": delta,
        "bundles": entries,
        "policy": "Proof Vault is a history of immutable BL3 application snapshots. VALID only means stored JSON still matches its SHA-256 fingerprint; it is not an onchain attestation or external identity credential."
    }


@app.route("/api/hunter-proof-vault/<username>")
def hunter_proof_vault_api(username):
    snap = _proof_vault_snapshot(username, request.args.get("limit", 30))
    if snap is None:
        return jsonify({"success": False, "message": "Hunter not found"}), 404
    return jsonify(snap)


@app.route("/proof-vault/<username>")
def proof_vault_page(username):
    snap = _proof_vault_snapshot(username, 50)
    if snap is None:
        return "Hunter not found", 404
    esc = lambda v: html.escape(str(v or ""))
    latest = snap.get("latest") or {}
    delta = snap.get("latest_delta") or {}
    def signed(v):
        try:
            n = int(v or 0)
        except Exception:
            n = 0
        return ("+" if n > 0 else "") + str(n)
    rows_html = ""
    for item in snap.get("bundles") or []:
        state_class = "ok" if item.get("integrity") == "VALID" else "bad"
        rows_html += f'''<article class="bundle"><div><div class="eyebrow">{esc(item.get("created_at"))}</div><h3>{esc(item.get("bundle_id"))}</h3><div class="meta">{esc(item.get("identity_state"))} · {esc(item.get("reputation"))} REP · {esc(item.get("proof_events"))} proof events · score {esc(item.get("proof_score"))}</div></div><div class="right"><b class="{state_class}">{esc(item.get("integrity"))}</b><a href="/proof-bundle/{urllib.parse.quote(str(item.get("bundle_id") or ""))}">OPEN ↗</a></div></article>'''
    if not rows_html:
        rows_html = '<div class="empty">No sealed proof bundles yet. Seal a snapshot from the Hunter dashboard to start the vault.</div>'
    latest_stats = f'''<div class="stat"><b>{esc(latest.get("reputation") if latest else 0)}</b><span>LATEST REP</span></div><div class="stat"><b>{esc(latest.get("proof_events") if latest else 0)}</b><span>PROOF EVENTS</span></div><div class="stat"><b>{esc(snap.get("bundle_count"))}</b><span>SEALED BUNDLES</span></div><div class="stat"><b>{esc(snap.get("valid_count"))}</b><span>VALID SNAPSHOTS</span></div>'''
    delta_html = ""
    if delta:
        delta_html = f'''<div class="delta"><b>LATEST CHANGE</b><span>REP {signed(delta.get("reputation"))}</span><span>XP {signed(delta.get("xp"))}</span><span>WINS {signed(delta.get("wins"))}</span><span>PROOFS {signed(delta.get("proof_events"))}</span><span>SCORE {signed(delta.get("proof_score"))}</span></div>'''
    return f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(username)} // BL3 Proof Vault</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#050705;color:#fff;font-family:Inter,system-ui,Arial;padding:24px}}.wrap{{max-width:980px;margin:auto}}a{{color:inherit}}.brand{{font-size:24px;font-weight:950}}.brand span,.ok{{color:#b8ff5a}}.bad{{color:#ff6b7d}}.hero,.card{{margin-top:22px;border:1px solid #303729;border-radius:28px;padding:26px;background:linear-gradient(145deg,#0d120c,#090b09)}}.eyebrow{{font-size:10px;color:#b8ff5a;font-weight:950;letter-spacing:1.3px}}h1{{font-size:clamp(42px,8vw,76px);margin:8px 0}}h3{{margin:5px 0 8px}}.meta{{color:#9aa091;line-height:1.55}}.grid{{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:18px}}.stat{{border:1px solid #303729;border-radius:16px;padding:14px}}.stat b{{display:block;font-size:22px}}.stat span{{font-size:8px;color:#7f8778}}.delta{{display:flex;gap:9px;flex-wrap:wrap;margin-top:14px;padding:12px;border:1px solid rgba(184,255,90,.16);border-radius:14px}}.delta b{{color:#b8ff5a}}.delta span{{font:11px ui-monospace,monospace;color:#dbe9ce}}.bundle{{display:flex;justify-content:space-between;gap:18px;align-items:center;border-top:1px solid #242a20;padding:17px 0}}.bundle:first-child{{border-top:0}}.right{{display:flex;gap:12px;align-items:center;flex-wrap:wrap;justify-content:flex-end}}.right a,.actions a{{border:1px solid #38402f;border-radius:11px;padding:9px 11px;text-decoration:none;font-weight:900;font-size:11px}}.actions{{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}}.empty{{color:#9aa091;padding:24px 0}}@media(max-width:720px){{.grid{{grid-template-columns:repeat(2,1fr)}}.bundle{{align-items:flex-start;flex-direction:column}}.right{{justify-content:flex-start}}}}</style></head><body><div class="wrap"><div class="brand">BL3<span>●</span> PROOF VAULT</div><section class="hero"><div class="eyebrow">BUNDLE HISTORY // V18.3</div><h1>{esc(username)}</h1><div class="meta">Browse immutable snapshots of this Hunter's BL3 Passport + Proof Ledger over time.</div><div class="grid">{latest_stats}</div>{delta_html}<div class="actions"><a href="/passport/{urllib.parse.quote(username)}">HUNTER PASSPORT</a><a href="/proof-ledger/{urllib.parse.quote(username)}">LIVE PROOF LEDGER</a><a href="/api/hunter-proof-vault/{urllib.parse.quote(username)}">VAULT JSON</a></div></section><section class="card"><div class="eyebrow">SEALED HISTORY</div>{rows_html}<div class="meta" style="margin-top:18px">{esc(snap.get("policy"))}</div></section></div></body></html>'''



# ===== V18.3 REPUTATION GRAPH + PROOF CONSTELLATION =====
def _clamp100(value):
    try: return max(0,min(100,int(round(float(value)))))
    except Exception: return 0

def _hunter_reputation_graph_snapshot(username):
    username=(username or "").strip(); p=_hunter_passport_snapshot(username); l=_hunter_proof_ledger_snapshot(username,limit=80); lo=_hunter_loadout_snapshot(username); v=_proof_vault_snapshot(username,limit=30)
    rep,xp,wins=int(p.get("reputation") or 0),int(p.get("xp") or 0),int(p.get("wins") or 0); streak,trophies,network=int(p.get("streak") or 0),int(p.get("trophies") or 0),int(p.get("network") or 0); badges=int(p.get("badges_unlocked") or 0); events=int(l.get("event_count") or 0); pscore=int(l.get("proof_score") or 0); bundles=list(v.get("bundles") or []); valid=sum(1 for x in bundles if x.get("valid")); verified=bool(p.get("wallet_verified"))
    dims=[
      {"key":"identity","label":"IDENTITY","icon":"🔐","score":_clamp100((35 if verified else 0)+min(45,rep*.45)+min(20,badges*4)),"detail":f"{'Wallet verified' if verified else 'Wallet not verified'} · {rep} reputation"},
      {"key":"activity","label":"ACTIVITY","icon":"⚡","score":_clamp100(min(55,streak*5)+min(45,xp/25)),"detail":f"{streak}-day streak · {xp} XP"},
      {"key":"battle","label":"BATTLE","icon":"⚔️","score":_clamp100(min(70,wins*7)+min(30,trophies*6)),"detail":f"{wins} wins · {trophies} trophies"},
      {"key":"network","label":"NETWORK","icon":"🕸️","score":_clamp100(min(100,network*10)),"detail":f"{network} network signals"},
      {"key":"achievement","label":"ACHIEVEMENT","icon":"🏅","score":_clamp100(min(100,badges*9)),"detail":f"{badges} badges · {lo.get('aura','SIGNAL')} aura"},
      {"key":"proof","label":"PROOF","icon":"🧾","score":_clamp100(min(60,events*4)+min(25,pscore/4)+min(15,valid*5)),"detail":f"{events} ledger events · {valid} valid snapshots"}]
    scores=[x["score"] for x in dims]; avg=sum(scores)/len(scores) if scores else 0; spread=max(scores)-min(scores) if scores else 0; balance=_clamp100(avg-spread*.28); overall=_clamp100(avg); strongest=max(dims,key=lambda x:x["score"]); state="CONSTELLATION" if overall>=75 and balance>=55 else ("FORMING" if overall>=45 else "EMERGING")
    canonical=json.dumps({"username":username,"dimensions":dims,"balance":balance,"overall":overall},sort_keys=True,separators=(",",":"))
    return {"success":True,"version":"V18.3","username":username,"identity_state":p.get("identity_state") or "NEW","graph_state":state,"overall_score":overall,"balance_score":balance,"strongest_signal":strongest,"dimensions":dims,"proof_events":events,"bundle_count":len(bundles),"valid_bundle_count":valid,"digest":hashlib.sha256(canonical.encode()).hexdigest(),"policy":"BL3 application signals only; not a universal identity score, credit score, financial rating, or external attestation."}

