# ===== V18.3 NEMESIS LADDER + RIVALRY HEAT =====
def _nemesis_ladder_snapshot(username, days=30, limit=10):
    public = _hunter_public_snapshot(username)
    if not public:
        return {"success": False, "message": "Hunter not found"}
    try:
        days = max(7, min(int(days or 30), 180))
    except Exception:
        days = 30
    try:
        limit = max(1, min(int(limit or 10), 30))
    except Exception:
        limit = 10
    cutoff = (datetime.utcnow() - timedelta(days=days)).isoformat()
    conn = db()
    battles = conn.execute(
        """SELECT id, challenger, opponent, winner, challenger_power, opponent_power, created_at
           FROM creature_battles
           WHERE (challenger = ? OR opponent = ?) AND created_at >= ?
           ORDER BY id DESC""",
        (username, username, cutoff),
    ).fetchall()
    challenges = conn.execute(
        """SELECT challenger, opponent, status, created_at
           FROM challenge_requests
           WHERE (challenger = ? OR opponent = ?) AND created_at >= ?
           ORDER BY id DESC""",
        (username, username, cutoff),
    ).fetchall()
    conn.close()

    by_rival = {}
    for b in battles:
        rival = b["opponent"] if b["challenger"] == username else b["challenger"]
        if not rival or rival == username:
            continue
        x = by_rival.setdefault(rival, {"username": rival, "clashes": 0, "wins": 0, "losses": 0, "power_gap_total": 0, "last_clash": "", "pending_challenges": 0, "challenge_count": 0})
        x["clashes"] += 1
        if b["winner"] == username:
            x["wins"] += 1
        elif b["winner"] == rival:
            x["losses"] += 1
        my_power = b["challenger_power"] if b["challenger"] == username else b["opponent_power"]
        rival_power = b["opponent_power"] if b["challenger"] == username else b["challenger_power"]
        x["power_gap_total"] += abs(int(my_power or 0) - int(rival_power or 0))
        if not x["last_clash"]:
            x["last_clash"] = b["created_at"] or ""

    for c in challenges:
        rival = c["opponent"] if c["challenger"] == username else c["challenger"]
        if not rival or rival == username:
            continue
        x = by_rival.setdefault(rival, {"username": rival, "clashes": 0, "wins": 0, "losses": 0, "power_gap_total": 0, "last_clash": "", "pending_challenges": 0, "challenge_count": 0})
        x["challenge_count"] += 1
        if (c["status"] or "").lower() == "pending":
            x["pending_challenges"] += 1

    rivals = []
    for rival, x in by_rival.items():
        clashes = int(x["clashes"])
        avg_gap = round(x["power_gap_total"] / clashes, 1) if clashes else None
        closeness = max(0, 28 - min(28, int(avg_gap // 4))) if avg_gap is not None else 0
        activity = min(45, clashes * 12)
        challenge_heat = min(18, x["challenge_count"] * 4 + x["pending_challenges"] * 6)
        recency = 0
        if x["last_clash"]:
            try:
                dt = datetime.fromisoformat(str(x["last_clash"]).replace("Z", "+00:00")).replace(tzinfo=None)
                age = max(0, (datetime.utcnow() - dt).days)
                recency = max(0, 18 - age)
            except Exception:
                recency = 0
        heat = max(0, min(100, int(round(activity + closeness + challenge_heat + recency))))
        tier = "🔥 ARCH NEMESIS" if heat >= 80 else "⚔️ HEATED RIVAL" if heat >= 60 else "⚡ ACTIVE RIVAL" if heat >= 35 else "🧊 COOLING"
        rivals.append({
            "username": rival, "heat": heat, "tier": tier, "clashes": clashes,
            "wins": int(x["wins"]), "losses": int(x["losses"]), "avg_power_gap": avg_gap,
            "pending_challenges": int(x["pending_challenges"]), "challenge_count": int(x["challenge_count"]),
            "last_clash": x["last_clash"],
            "h2h_url": "/rival-dossier/" + urllib.parse.quote(username) + "/" + urllib.parse.quote(rival),
            "profile_url": "/hunter/" + urllib.parse.quote(rival),
        })
    rivals.sort(key=lambda r: (r["heat"], r["clashes"], r["challenge_count"]), reverse=True)
    rivals = rivals[:limit]
    return {
        "success": True, "username": username, "window_days": days,
        "total_clashes": len(battles), "total_challenges": len(challenges),
        "top_nemesis": rivals[0] if rivals else None, "rivals": rivals,
        "policy": "Rivalry Heat is an in-app BL3 gameplay signal derived from recent Clashes, challenge activity and matchup closeness. It is not a real-world ranking, reputation judgment or prediction of a person."
    }


