# ===== V18.3 RIVALRY RECAP + SEASON SHARE CARDS =====
def _rivalry_season_key(value=None):
    raw = (str(value or "").strip() or datetime.utcnow().strftime("%Y-%m"))
    try:
        dt = datetime.strptime(raw, "%Y-%m")
        return dt.strftime("%Y-%m")
    except Exception:
        return datetime.utcnow().strftime("%Y-%m")


def _rivalry_season_snapshot(username, season_key=None):
    username = (username or "").strip()
    season_key = _rivalry_season_key(season_key)
    conn = db()
    user = conn.execute("SELECT username FROM users WHERE username = ?", (username,)).fetchone()
    if not user:
        conn.close()
        return {"success": False, "message": "Hunter not found"}
    battles = conn.execute("SELECT id, challenger, opponent, winner, challenger_power, opponent_power, created_at FROM creature_battles WHERE substr(created_at,1,7)=? AND (challenger=? OR opponent=?) ORDER BY id DESC", (season_key, username, username)).fetchall()
    challenges = conn.execute("SELECT challenger, opponent, status, created_at FROM challenge_requests WHERE substr(created_at,1,7)=? AND (challenger=? OR opponent=?) ORDER BY id DESC", (season_key, username, username)).fetchall()
    conn.close()
    rivals = {}
    wins = losses = 0
    for b in battles:
        rival = b["opponent"] if b["challenger"] == username else b["challenger"]
        if not rival or rival == username:
            continue
        r = rivals.setdefault(rival, {"username": rival, "clashes": 0, "wins": 0, "losses": 0, "points": 0, "last_clash": ""})
        r["clashes"] += 1
        if b["winner"] == username:
            wins += 1; r["wins"] += 1; r["points"] += 3
        else:
            losses += 1; r["losses"] += 1; r["points"] += 1
        if not r["last_clash"]:
            r["last_clash"] = b["created_at"] or ""
    pending = 0
    for c in challenges:
        rival = c["opponent"] if c["challenger"] == username else c["challenger"]
        if not rival or rival == username:
            continue
        r = rivals.setdefault(rival, {"username": rival, "clashes": 0, "wins": 0, "losses": 0, "points": 0, "last_clash": ""})
        if (c["status"] or "").lower() == "pending":
            pending += 1
            r["points"] += 1
    rows = list(rivals.values())
    rows.sort(key=lambda x: (x["points"], x["clashes"], x["wins"]), reverse=True)
    clashes = len(battles)
    unique_rivals = len(rows)
    score = min(100, clashes * 8 + wins * 5 + unique_rivals * 4 + pending * 2)
    season_title = "👑 RIVALRY ICON" if score >= 80 else "🔥 NEMESIS HUNTER" if score >= 55 else "⚔️ SEASON DUELIST" if score >= 30 else "⚡ RIVALRY SPARK" if score >= 10 else "🧊 UNRANKED"
    try:
        label = datetime.strptime(season_key, "%Y-%m").strftime("%B %Y").upper()
    except Exception:
        label = season_key
    return {"success": True, "username": username, "season_key": season_key, "season_label": label, "season_title": season_title, "season_score": score, "clashes": clashes, "wins": wins, "losses": losses, "unique_rivals": unique_rivals, "pending_challenges": pending, "top_nemesis": rows[0] if rows else None, "rivals": rows[:20], "policy": "Season titles are in-app BL3 gameplay labels derived from this season's challenge and Clash activity. They are not real-world rankings, evaluations, or predictions about people."}


