# ===== V18.3 RIVALRY AWARDS + SEASON HONORS =====
def _rivalry_awards_snapshot(season_key=None):
    season_key = _rivalry_season_key(season_key)
    conn = db()
    users = [r["username"] for r in conn.execute("SELECT username FROM users ORDER BY username ASC").fetchall()]
    conn.close()
    rows = []
    for username in users:
        d = _rivalry_season_snapshot(username, season_key)
        if not d.get("success"):
            continue
        row = {
            "username": username,
            "season_score": int(d.get("season_score") or 0),
            "wins": int(d.get("wins") or 0),
            "losses": int(d.get("losses") or 0),
            "clashes": int(d.get("clashes") or 0),
            "unique_rivals": int(d.get("unique_rivals") or 0),
            "pending_challenges": int(d.get("pending_challenges") or 0),
        }
        if row["clashes"] or row["pending_challenges"]:
            row["legacy_url"] = "/rivalry-legacy/" + urllib.parse.quote(username)
            row["season_url"] = "/rivalry-season/" + urllib.parse.quote(username) + "?season=" + urllib.parse.quote(season_key)
            rows.append(row)
    try:
        label = datetime.strptime(season_key, "%Y-%m").strftime("%B %Y").upper()
    except Exception:
        label = season_key
    def pick(key, label_text, icon, detail_template):
        if not rows:
            return None
        winner = max(rows, key=lambda x: (x.get(key, 0), x["season_score"], x["wins"], x["clashes"]))
        value = int(winner.get(key) or 0)
        if value <= 0:
            return None
        return {
            "key": key, "label": label_text, "icon": icon,
            "username": winner["username"], "value": value,
            "detail": detail_template.format(value=value),
            "legacy_url": winner["legacy_url"], "season_url": winner["season_url"]
        }
    awards = [x for x in [
        pick("season_score", "SEASON SIGNAL", "👑", "{value}/100 season score across recorded BL3 rivalry activity."),
        pick("wins", "CLUTCH HUNTER", "🏆", "{value} recorded rivalry win(s) this season."),
        pick("clashes", "CLASH GRINDER", "⚔️", "{value} recorded Clash(es) this season."),
        pick("unique_rivals", "RIVAL NETWORK", "🕸️", "Faced {value} unique rival(s) this season."),
        pick("pending_challenges", "CHALLENGE SPARK", "🎯", "{value} pending challenge signal(s) in this season snapshot."),
    ] if x]
    total_clashes = sum(r["clashes"] for r in rows) // 2 if rows else 0
    state = "🏅 HONORS LIVE" if len(awards) >= 3 else "⚡ AWARDS FORMING" if rows else "🧊 QUIET SEASON"
    digest_payload = {"season": season_key, "awards": [(a["key"], a["username"], a["value"]) for a in awards]}
    digest = hashlib.sha256(json.dumps(digest_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    return {
        "success": True, "version": "V18.3", "season_key": season_key, "season_label": label,
        "awards_state": state, "active_hunters": len(rows), "total_clashes": total_clashes,
        "awards": awards, "season_digest": digest,
        "policy": "Season honors are descriptive in-app BL3 gameplay labels derived from recorded challenges and Clashes. They are not real-world rankings, evaluations, predictions, or judgments of people."
    }

