# ===== V18.3 RIVALRY TROPHY CASE + AWARDS ARCHIVE =====
def _rivalry_award_season_keys(limit=18):
    """Return recent season keys backed by recorded rivalry activity."""
    limit = max(1, min(int(limit or 18), 60))
    conn = db()
    keys = set()
    try:
        for row in conn.execute("SELECT DISTINCT season_key FROM creature_battles WHERE COALESCE(season_key,'') <> ''").fetchall():
            key = str(row["season_key"] or "").strip()
            if key:
                keys.add(key)
        for row in conn.execute("SELECT DISTINCT substr(created_at,1,7) AS season_key FROM challenge_requests WHERE length(created_at) >= 7").fetchall():
            key = str(row["season_key"] or "").strip()
            if key:
                keys.add(key)
    finally:
        conn.close()
    valid = []
    for key in keys:
        try:
            datetime.strptime(key, "%Y-%m")
            valid.append(key)
        except Exception:
            continue
    return sorted(valid, reverse=True)[:limit]


def _rivalry_awards_archive_snapshot(limit=18):
    limit = max(1, min(int(limit or 18), 60))
    seasons = []
    honor_counts = defaultdict(int)
    hunter_counts = defaultdict(int)
    for season_key in _rivalry_award_season_keys(limit):
        snap = _rivalry_awards_snapshot(season_key)
        awards = list(snap.get("awards") or [])
        if not awards:
            continue
        season_item = {
            "season_key": season_key,
            "season_label": snap.get("season_label") or season_key,
            "awards_state": snap.get("awards_state") or "",
            "season_digest": snap.get("season_digest") or "",
            "active_hunters": int(snap.get("active_hunters") or 0),
            "total_clashes": int(snap.get("total_clashes") or 0),
            "awards": awards,
        }
        seasons.append(season_item)
        for award in awards:
            honor_counts[str(award.get("key") or "award")] += 1
            hunter_counts[str(award.get("username") or "")] += 1
    all_honors = sum(len(x["awards"]) for x in seasons)
    most_honored = None
    if hunter_counts:
        username, count = max(hunter_counts.items(), key=lambda kv: (kv[1], kv[0].lower()))
        if username:
            most_honored = {"username": username, "honors": int(count), "url": "/trophy-case/" + urllib.parse.quote(username)}
    digest_payload = {"seasons": [(x["season_key"], x["season_digest"]) for x in seasons], "all_honors": all_honors}
    archive_digest = hashlib.sha256(json.dumps(digest_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    return {"success": True, "version": "V18.3", "seasons": seasons, "season_count": len(seasons), "all_honors": all_honors, "award_type_counts": dict(honor_counts), "most_honored": most_honored, "archive_digest": archive_digest, "policy": "The archive recalculates descriptive in-app BL3 rivalry honors from recorded challenge and Clash data. It is not an external ranking or real-world evaluation of people."}


def _hunter_trophy_case_snapshot(username, limit=36):
    username = str(username or "").strip()[:80]
    conn = db()
    exists = conn.execute("SELECT 1 FROM users WHERE username = ?", (username,)).fetchone()
    conn.close()
    if not exists:
        return {"success": False, "message": "Hunter not found.", "username": username}
    seasons = _rivalry_awards_archive_snapshot(limit).get("seasons") or []
    trophies = []
    by_type = defaultdict(int)
    honored_seasons = set()
    for season in seasons:
        for award in season.get("awards") or []:
            if str(award.get("username") or "").lower() != username.lower():
                continue
            item = dict(award)
            item["season_key"] = season.get("season_key")
            item["season_label"] = season.get("season_label")
            item["season_digest"] = season.get("season_digest")
            trophies.append(item)
            by_type[str(item.get("key") or "award")] += 1
            honored_seasons.add(str(season.get("season_key") or ""))
    trophy_weights = {"season_score": 5, "wins": 4, "clashes": 3, "unique_rivals": 2, "pending_challenges": 1}
    trophy_score = sum(trophy_weights.get(str(t.get("key") or ""), 1) for t in trophies)
    if trophy_score >= 30:
        state = "👑 TROPHY LEGEND"
    elif trophy_score >= 16:
        state = "🔥 HONORS STACKED"
    elif trophy_score >= 7:
        state = "🏆 TROPHY HUNTER"
    elif trophies:
        state = "⚡ FIRST HONORS"
    else:
        state = "🧊 CASE EMPTY"
    digest_payload = {"username": username, "trophies": [(t.get("season_key"), t.get("key"), t.get("value")) for t in trophies]}
    trophy_digest = hashlib.sha256(json.dumps(digest_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    return {"success": True, "version": "V18.3", "username": username, "trophy_state": state, "trophy_score": int(trophy_score), "total_honors": len(trophies), "honored_seasons": len(honored_seasons), "unique_award_types": len(by_type), "award_type_counts": dict(by_type), "trophies": trophies, "trophy_digest": trophy_digest, "policy": "This trophy case summarizes descriptive BL3 in-app rivalry honors earned from recorded gameplay signals. It is not a real-world ranking or credential."}


