def rivalry_awards_archive_page():
    try:
        limit = int(request.args.get("limit") or 18)
    except Exception:
        limit = 18
    d = _rivalry_awards_archive_snapshot(limit)
    esc = html.escape
    most = d.get("most_honored") or {}
    season_html = []
    for season in d.get("seasons") or []:
        award_cards = "".join(
            '<article class="award"><div class="icon">{}</div><div><div class="eyebrow">{}</div><h3>{}</h3><p>{}</p><a href="/trophy-case/{}">TROPHY CASE ↗</a></div></article>'.format(
                esc(str(a.get("icon") or "🏅")), esc(str(a.get("label") or "HONOR")), esc(str(a.get("username") or "")), esc(str(a.get("detail") or "")), urllib.parse.quote(str(a.get("username") or ""))
            ) for a in season.get("awards") or []
        )
        season_html.append('<section class="panel"><div class="season-head"><div><div class="eyebrow">{}</div><h2>{}</h2></div><div class="state">{}</div></div><div class="awards">{}</div><div class="digest">SEASON DIGEST // {}</div></section>'.format(esc(str(season.get("season_key") or "")), esc(str(season.get("season_label") or "")), esc(str(season.get("awards_state") or "")), award_cards, esc(str(season.get("season_digest") or ""))))
    body = "".join(season_html) or '<section class="panel empty">No archived season honors yet.</section>'
    most_html = ""
