# ===== V18.3 RIVALRY CHAMPIONSHIP + PLAYOFF BRACKET =====
def _rivalry_championship_snapshot(season_key=None, bracket_size=8):
    season_key = _rivalry_season_key(season_key)
    try:
        bracket_size = int(bracket_size or 8)
    except Exception:
        bracket_size = 8
    bracket_size = 8 if bracket_size >= 8 else 4
    conn = db()
    users = [r["username"] for r in conn.execute("SELECT username FROM users ORDER BY username ASC").fetchall()]
    conn.close()
    seeds = []
    for username in users:
        snap = _rivalry_season_snapshot(username, season_key)
        if not snap.get("success"):
            continue
        row = {
            "username": username,
            "season_score": int(snap.get("season_score") or 0),
            "wins": int(snap.get("wins") or 0),
            "losses": int(snap.get("losses") or 0),
            "clashes": int(snap.get("clashes") or 0),
            "unique_rivals": int(snap.get("unique_rivals") or 0),
            "season_title": snap.get("season_title") or "🧊 UNRANKED",
        }
        if row["clashes"] or row["wins"] or row["losses"]:
            seeds.append(row)
    seeds.sort(key=lambda x: (x["season_score"], x["wins"], x["clashes"], x["unique_rivals"], x["username"]), reverse=True)
    seeds = seeds[:bracket_size]
    for i, row in enumerate(seeds, start=1):
        row["seed"] = i
        row["profile_url"] = "/hunter/" + urllib.parse.quote(row["username"])
        row["season_url"] = "/rivalry-season/" + urllib.parse.quote(row["username"]) + "?season=" + urllib.parse.quote(season_key)
    pairs = []
    left, right = 0, len(seeds) - 1
    while left < right:
        a, b = seeds[left], seeds[right]
        dossier = _rival_dossier_snapshot(a["username"], b["username"], 50)
        pairs.append({
            "match": len(pairs) + 1,
            "a": a,
            "b": b,
            "h2h": {
                "clashes": int(dossier.get("total_clashes") or 0),
                "a_wins": int(dossier.get("wins") or 0),
                "b_wins": int(dossier.get("losses") or 0),
            },
            "h2h_url": "/rival-dossier/{}/{}".format(urllib.parse.quote(a["username"]), urllib.parse.quote(b["username"])),
        })
        left += 1
        right -= 1
    try:
        season_label = datetime.strptime(season_key, "%Y-%m").strftime("%B %Y").upper()
    except Exception:
        season_label = season_key
    state = "🏆 PLAYOFF READY" if len(seeds) >= bracket_size else "⚡ BRACKET FORMING" if len(seeds) >= 2 else "🧊 WAITING FOR RIVALS"
    digest_payload = {
        "season": season_key,
        "seeds": [(x["seed"], x["username"], x["season_score"], x["wins"], x["clashes"]) for x in seeds],
        "pairs": [(p["match"], p["a"]["username"], p["b"]["username"], p["h2h"]["clashes"]) for p in pairs],
    }
    digest = hashlib.sha256(json.dumps(digest_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()
    round_key = "quarterfinals" if bracket_size == 8 else "semifinals"
    return {
        "success": True,
        "version": "V18.3",
        "season_key": season_key,
        "season_label": season_label,
        "bracket_size": bracket_size,
        "qualified": len(seeds),
        "championship_state": state,
        "seeds": seeds,
        round_key: pairs,
        "championship_digest": digest,
        "policy": "The Championship bracket is a descriptive BL3 gameplay seeding view derived from recorded season rivalry activity. It does not predict future winners or evaluate people outside the game. Advancement is not automatic; future Clash results must be recorded in BL3."
    }


@app.route("/api/rivalry-championship")
def rivalry_championship_api():
    return jsonify(_rivalry_championship_snapshot(request.args.get("season"), request.args.get("size", 8)))


