@app.route("/admin/championship-title/seal", methods=["POST"])
def championship_title_seal():
    if not _admin_ok():
        return jsonify({"success": False, "message": "Admin authorization required."}), 403
    body = request.get_json(silent=True) or request.form or {}
    season_key = _rivalry_season_key(body.get("season"))
    try:
        bracket_size = 8 if int(body.get("size") or 8) >= 8 else 4
    except Exception:
        return jsonify({"success": False, "message": "Invalid bracket size."}), 400
    existing = _championship_title_lookup(season_key, bracket_size)
    if existing:
        return jsonify({"success": True, "message": "Championship title already sealed.", "title": existing, "verify": _championship_title_verify(existing)})
    snap = _championship_match_center_snapshot(season_key, bracket_size)
    champion = snap.get("champion") or {}
    final = (snap.get("final") or [None])[0]
    if not champion or not final or not final.get("resolved"):
        return jsonify({"success": False, "message": "A verified recorded final Clash is required before sealing a championship title."}), 409
    champion_name = str(champion.get("username") or "")
    final_battle_id = int(final.get("battle_id") or 0)
    final_result_digest = str(final.get("result_digest") or "")
    match_center_digest = str(snap.get("match_center_digest") or "")
    if not champion_name or final_battle_id < 1 or not final_result_digest or not match_center_digest:
        return jsonify({"success": False, "message": "Final evidence is incomplete; title not sealed."}), 409
    sealed_at = datetime.utcnow().isoformat(timespec="seconds") + "Z"
    payload = {
        "season_key": season_key,
        "bracket_size": bracket_size,
        "champion": champion_name,
        "final_battle_id": final_battle_id,
        "final_result_digest": final_result_digest,
        "match_center_digest": match_center_digest,
        "sealed_at": sealed_at,
    }
    title_digest = hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")).hexdigest()
    try:
        conn = db()
        conn.execute(
            """INSERT INTO championship_titles
               (season_key,bracket_size,champion,final_battle_id,final_result_digest,match_center_digest,sealed_at,title_digest)
               VALUES (?,?,?,?,?,?,?,?)""",
            (season_key, bracket_size, champion_name, final_battle_id, final_result_digest, match_center_digest, sealed_at, title_digest),
        )
        conn.commit(); conn.close()
    except sqlite3.IntegrityError:
        row = _championship_title_lookup(season_key, bracket_size)
        return jsonify({"success": True, "message": "Championship title already sealed.", "title": row, "verify": _championship_title_verify(row)})
    except Exception as exc:
        return jsonify({"success": False, "message": "Could not seal championship title.", "error": type(exc).__name__}), 500
    _admin_action("championship_title_seal", True, "{} size {} champion {} battle {}".format(season_key, bracket_size, champion_name, final_battle_id))
    row = _championship_title_lookup(season_key, bracket_size)
    return jsonify({"success": True, "message": "Championship title sealed into the immutable registry.", "title": row, "verify": _championship_title_verify(row)})


@app.route("/api/championship-title/<season_key>")
def championship_title_api(season_key):
    try:
        bracket_size = 8 if int(request.args.get("size", 8)) >= 8 else 4
    except Exception:
        bracket_size = 8
    row = _championship_title_lookup(_rivalry_season_key(season_key), bracket_size)
    if not row:
        return jsonify({"success": False, "message": "Sealed championship title not found."}), 404
    return jsonify({"success": True, "title": row, "verify": _championship_title_verify(row)})


