# ===== V21.7 GUESTBOOK EDIT + REPLY BACK + EXPORT =====
@app.post("/api/hunter/guestbook/edit")
def hunter_guestbook_edit():
    actor = str(session.get("authenticated_username") or "").strip()
    if not actor:
        return jsonify({"success": False, "message": "Login required."}), 401
    payload = request.get_json(silent=True) or request.form or {}
    try:
        entry_id = int(payload.get("entry_id") or 0)
    except Exception:
        entry_id = 0
    reaction = str(payload.get("reaction") or "🔥").strip() or "🔥"
    message = " ".join(str(payload.get("message") or "").replace("\n", " ").split()).strip()
    if entry_id <= 0:
        return jsonify({"success": False, "message": "Valid entry_id required."}), 400
    if reaction not in HUNTER_KUDOS_REACTIONS:
        return jsonify({"success": False, "message": "Unsupported reaction."}), 400
    if not message:
        return jsonify({"success": False, "message": "Message required."}), 400
    if len(message) > 180:
        return jsonify({"success": False, "message": "Message too long (max 180 chars)."}), 400
    conn = db()
    row = conn.execute("SELECT id, recipient, author FROM hunter_guestbook_entries WHERE id = ?", (entry_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify({"success": False, "message": "Entry not found."}), 404
    if str(row["author"] or "").lower() != actor.lower():
        conn.close()
        return jsonify({"success": False, "message": "Only the original author can edit this Kudos."}), 403
    conn.execute("UPDATE hunter_guestbook_entries SET reaction = ?, message = ? WHERE id = ? AND author = ?", (reaction, message, entry_id, actor))
    conn.commit()
    recipient = str(row["recipient"] or "")
    conn.close()
    return jsonify({"success": True, "message": "Kudos updated.", "entry_id": entry_id, "guestbook": _hunter_guestbook_snapshot(recipient, limit=24)})


